    if len(value) != 8 or not value.isdigit():
        raise ValueError(f"invalid YYYYMMDD date: {value!r}")
    return date(int(value[:4]), int(value[4:6]), int(value[6:8]))


def _datediff(first: str, second: str) -> int:
